// Claude replies with a JSON object as plain text content - parse it
// defensively, and drop anything that doesn't look like a real lead
// rather than posting garbage into the tracker.
const PLATFORM_ID = 'REPLACE-WITH-PLATFORM-UUID-FOR-THIS-MAILBOX-SOURCE';
const out = [];
for (const item of items) {
  try {
    const text = item.json.content?.[0]?.text ?? '{}';
    const parsed = JSON.parse(text);
    if (!parsed.tender_no || !parsed.closing_at) continue;
    out.push({
      json: {
        tenderNo: String(parsed.tender_no).slice(0, 120),
        client: String(parsed.client || 'Unknown').slice(0, 300),
        title: String(parsed.title || '').slice(0, 500),
        closingAt: new Date(parsed.closing_at).toISOString(),
        sourcePlatformId: PLATFORM_ID,
      },
    });
  } catch (e) {
    continue;
  }
}
return out;
